const input = $('When Executed by Another Workflow').first()?.json || {};
const date = String(input.preferred_date || '');
const time = String(input.preferred_time || '');
const duration = Number(input.duration_minutes || 60);
const dateMatch = /^(\d{4})-(\d{2})-(\d{2})$/.exec(date);
const timeMatch = /^(\d{2}):(\d{2})$/.exec(time);
let error = '';
const parsedDate = dateMatch ? new Date(`${date}T00:00:00Z`) : null;
const validCalendarDate = !!parsedDate && Number.isFinite(parsedDate.getTime()) && parsedDate.toISOString().slice(0, 10) === date;
if (!dateMatch || !timeMatch || Number(timeMatch[1]) > 23 || Number(timeMatch[2]) > 59 || !validCalendarDate) {
  error = 'Provide a valid preferred_date (YYYY-MM-DD) and preferred_time (HH:mm).';
} else if (!Number.isInteger(duration) || duration < 15 || duration > 480) {
  error = 'Appointment duration must be between 15 and 480 minutes.';
}
return [{ json: {
  success: !error, appointment_ready: !error, error_type: error ? 'validation' : undefined, error,
  business_id: input.business_id, contact_id: input.contact_id, conversation_id: input.conversation_id,
  appointment_type: input.appointment_type || 'consultation', title: input.title || 'Appointment',
  location: input.location || null, description: input.description || null,
  preferred_date: date, preferred_time: time, duration_minutes: duration,
  assigned_to: input.assigned_to || null
} }];

const input = $('When Executed by Another Workflow').first()?.json || {};
return [{
  json: {
    success: false,
    message: input.error || 'Validation failed.',
    contact_id: input.contact_id,
    conversation_id: input.conversation_id
  }
}];

const result = $json || {};
const appointment = result.data?.appointment;
if (result.success && appointment?.id) {
  const details = result.data;
  const time = details.localTimeLabel || appointment.starts_at;
  const notices = [];
  if (!details.customerConfirmationSent) notices.push('Customer confirmation could not be sent');
  if (appointment.assigned_to && !details.staffNotified) notices.push('Staff WhatsApp notification could not be sent');
  return [{ json: { success: true,
    message: `Appointment confirmed for ${time}${appointment.location ? ` at ${appointment.location}` : ''}.${notices.length ? ` ${notices.join('; ')}.` : ''}`,
    appointment, customer_confirmation_sent: details.customerConfirmationSent,
    staff_notified: details.staffNotified, assigned_to: details.assignedTo
  } }];
}
const error = result.error?.message || result.error || result.message || 'Appointment could not be booked.';
return [{ json: { success: false, error: true, message: String(error), contact_id: $('When Executed by Another Workflow').first()?.json?.contact_id, conversation_id: $('When Executed by Another Workflow').first()?.json?.conversation_id } }];
